import React from "react";
import {
  FaUserEdit,
  FaMapMarkerAlt,
  FaImage,
  FaMicrochip,
  FaTag,
  FaQuestionCircle,
  FaClock,
  FaSyncAlt,
  FaFileAlt,
  FaCoins,
  FaChevronLeft,
} from "react-icons/fa";
import { apiGet, apiPost } from "../common/api";
import InfoField from "../components/InfoField";
import Loader from "../common/Loader";
import withRouter from "../common/withRouter";

// صفحه‌ی جزئیات یک درخواست در «سوابق» — از InfoField مشترک استفاده می‌کنه
// وایر شده به GET /detail و برای تسویه به POST /end-request
class MyRequestDetailPage extends React.Component {
  constructor(props) {
    super(props);
    this.state = { request: null, loading: true, message: "" };
    this.handleBack = this.handleBack.bind(this);
    this.handleSettle = this.handleSettle.bind(this);
  }

  componentDidMount() {
    const { id } = this.props.params;
    apiGet(`/detail?id=${id}`)
      .then((json) => {
        this.setState({ request: json.request || null, loading: false });
      })
      .catch(() => {
        this.setState({ loading: false });
      });
  }

  handleBack() {
    this.props.navigate(-1);
  }

  handleSettle() {
    // TODO: این یک پیاده‌سازی حداقلی‌ست؛ در نسخه‌ی نهایی به‌جای prompt
    // باید یک فرم واقعی برای مبلغ کل، هزینه‌ی لوازم، توضیحات و آپلود فیش ساخته بشه.
    const { id } = this.props.params;
    const sum = window.prompt("کل مبلغ دریافتی (تومان):");
    if (sum === null) return;
    const abzar = window.prompt("هزینه لوازم مصرفی (تومان):", "0");
    if (abzar === null) return;
    const description = window.prompt("توضیحات پایان کار:", "");

    this.setState({ loading: true, message: "" });

    apiPost("/end-request", {
      id,
      end: 1,
      sum,
      abzar,
      abzar_details: "",
      end_description: description || "",
    })
      .then((json) => {
        this.setState({ loading: false, message: json.message || "" });
        if (json.status === "1") {
          this.props.navigate("/requests/history");
        }
      })
      .catch(() => {
        this.setState({ loading: false, message: "ارتباط با سرور برقرار نشد" });
      });
  }

  render() {
    const { request, loading, message } = this.state;

    return (
      <div dir="rtl" lang="fa" className="bg-white min-vh-100">
        {loading && <Loader />}

        <div className="container-fluid px-3 pt-4 pb-5" style={{ maxWidth: 480, margin: "0 auto" }}>
          <div className="d-flex justify-content-end mb-3">
            <button
              type="button"
              onClick={this.handleBack}
              className="btn btn-light rounded-circle border p-2 d-flex align-items-center justify-content-center"
              style={{ width: 36, height: 36 }}
            >
              <FaChevronLeft size={14} />
            </button>
          </div>

          {request && (
            <>
              <InfoField icon={<FaUserEdit size={18} />} label="نام مشتری" value={request.name} />
              <InfoField
                icon={<FaMapMarkerAlt size={18} />}
                label="استان"
                value={request.state_model ? request.state_model.name : ""}
              />
              <InfoField icon={<FaImage size={18} />} label="آدرس" value={request.address} />
              <InfoField icon={<FaMicrochip size={18} />} label="نوع دستگاه" value={request.device_type} />
              <InfoField icon={<FaTag size={18} />} label="برند دستگاه" value={request.device_brand} />
              <InfoField icon={<FaQuestionCircle size={18} />} label="ایراد دستگاه" value={request.problem} />
              <InfoField icon={<FaClock size={18} />} label="زمان مراجعه" value={request.time} />
              <InfoField icon={<FaSyncAlt size={18} />} label="توضیحات" value={request.description || "—"} />

              <InfoField icon={<FaFileAlt size={18} />} label="وضعیت">
                <span className="text-primary fw-semibold">
                  {request.end === 1 ? "تسویه شده" : request.status === -1 ? "لغو شده" : "در حال انجام"}
                </span>
              </InfoField>

              {request.sum ? (
                <InfoField icon={<FaCoins size={18} />} label="کل دریافتی">
                  <span className="fw-semibold">{request.sum} تومان</span>
                </InfoField>
              ) : null}

              {message && <div className="text-danger small text-center mb-3">{message}</div>}

              {request.end !== 1 && (
                <button
                  type="button"
                  onClick={this.handleSettle}
                  className="btn btn-primary w-100 rounded-3 py-3 mt-2"
                >
                  تسویه درخواست
                </button>
              )}
            </>
          )}
        </div>
      </div>
    );
  }
}

export default withRouter(MyRequestDetailPage);
